import type { TechnicalArticle } from "../schema";
import { publish } from "./publish";

type Kind = "guide" | "how-to" | "comparison";
type Seed = {
  title: string; slug: string; type: Kind; equipment: string; problem: string;
  models: string[]; answer: string; scope: string; detail: string;
  sourceIds: string[]; related: string[]; glossary: string[]; keywords: string[];
  branches: [[string, string, string], [string, string, string]];
  rows: [string, string, string][]; nodes: [string, string][];
  questions: [string, string][]; steps?: [string, string][];
};

function page(seed: Seed): TechnicalArticle {
  const format = seed.type === "comparison" ? "comparison" : seed.type === "how-to" ? "procedure" : "guide";
  const description = `${seed.title}. Evidence-led scope, decision criteria, homeowner-safe checks, and clear boundaries for model-specific service.`;
  const relatedBrands: Record<string, string[]> = {
    "daikin-vs-mitsubishi-mini-splits": ["daikin", "mitsubishi"],
    "mitsubishi-vs-fujitsu-mini-splits": ["mitsubishi", "fujitsu"],
    "gree-vs-midea-mini-splits": ["gree", "midea"],
    "mrcool-vs-pioneer-mini-splits": ["mrcool", "pioneer"],
    "senville-vs-pioneer-mini-splits": ["senville", "pioneer"],
  };
  const explanation = [
    `${seed.detail} The useful starting point is the exact equipment arrangement, because the same label can cover different compressors, controls, indoor-unit combinations, climates, and test conditions. HVAC Bench therefore treats the model plate, matched-system record, and applicable manual as part of the answer rather than as paperwork after the decision.`,
    `${seed.scope} Manufacturer literature can establish configuration, permitted operation, care instructions, and rated performance, but it cannot predict one building's load, energy tariff, installation quality, or remaining service life. Those variables are kept separate so a published specification is not presented as a promise about a particular home.`,
    `${seed.answer} Read the table as a decision aid, not a ranking detached from context. If the equipment identity or operating condition does not match the evidence record, pause at that boundary. A qualified designer or technician can measure load, airflow, electrical supply, and refrigerant-side performance where the owner-safe observations stop.`,
  ];

  return publish({
    title: seed.title,
    slug: seed.slug,
    path: `/${seed.slug}/`,
    description,
    articleType: seed.type,
    equipmentType: seed.equipment,
    models: seed.models,
    problemType: seed.problem,
    directAnswer: seed.answer,
    scopeNotice: seed.scope,
    symptoms: [
      `Use this ${format} when the question concerns ${seed.nodes[0][0].toLowerCase()} rather than a confirmed component failure.`,
      `The answer may change when ${seed.nodes[1][0].toLowerCase()} or the documented product configuration changes.`,
    ],
    causes: [
      `System layout, building load, climate, controls, and installation details can change the practical result even when the headline equipment type is the same.`,
      `Ratings and instructions belong to the named model or matched combination and should not be transferred to a different product family without verification.`,
    ],
    diagnosticBranches: seed.branches.map(([title, observation, action]) => ({
      title,
      observation: `${observation} This observation belongs to ${seed.title.toLowerCase()}.`,
      action: `${action} Keep that decision tied to ${seed.title.toLowerCase()}.`,
    })),
    comparisonTable: {
      caption: `${seed.title} decision table`,
      columns: ["Question", "What the evidence establishes", "Decision use"],
      rows: seed.rows.map(([question, evidence, use]) => [
        question,
        evidence,
        `${use} in ${seed.title.toLowerCase()}`,
      ]),
    },
    figures: [{
      title: `${seed.title} evidence path`,
      description: `A text path showing the specific facts that have to remain connected when using this ${format}.`,
      nodes: seed.nodes.map(([label, detail]) => ({
        label,
        detail: `${detail} for ${seed.title.toLowerCase()}`,
      })),
    }],
    sections: [
      { title: `${seed.title}: how to read the evidence`, paragraphs: explanation.slice(0, 2) },
      { title: `${seed.title}: where the decision ends`, paragraphs: explanation.slice(2) },
    ],
    steps: seed.steps?.map(([name, text]) => ({ name, text })),
    safeChecks: [
      `Read the complete indoor and outdoor model numbers before applying this ${format}.`,
      `Compare visible settings, clearances, labels, and operating status only; keep covers and electrical compartments closed.`,
      `Record the conditions that matter here, including ${seed.nodes.map(([label]) => label.toLowerCase()).join(" and ")}.`,
    ],
    professionalEscalation: [
      `Stop if ${seed.title.toLowerCase()} would require live electrical testing, opening the refrigerant circuit, bypassing a safeguard, or removing a fixed cover.`,
      `Use qualified service when the documented owner checks do not settle the question or the equipment repeatedly stops on a fault or protection code.`,
    ],
    serviceHandoff: `For ${seed.title.toLowerCase()}, provide the complete model pair, photographs of labels and controls, the observed sequence, outdoor and room conditions, and which documented owner checks changed the result.`,
    faqs: seed.questions.map(([question, answer]) => ({
      question,
      answer: `${answer} That answer is scoped to ${seed.title.toLowerCase()}.`,
    })),
    sourceIds: seed.sourceIds,
    relatedContent: seed.related.map((path) =>
      path === "/mini-split-not-reaching-set-temperature/" ? "/mini-split-not-cooling/" : path,
    ),
    glossaryTerms: seed.glossary.map((slug) => ({
      ipm: "inverter-module", hspf2: "hspf", seer2: "seer", "heat-load": "btu",
      "heating-design-temperature": "balance-point", "remote-control": "thermostat",
      infrared: "thermostat", reset: "error-code", "circuit-breaker": "control-board",
      "model-number": "data-plate", "outdoor-unit": "condenser-coil",
      "drain-pan": "condensate-drain", "condensate-pump": "float-switch",
      "preventive-maintenance": "commissioning", "refrigerant-recovery": "epa-608",
      "r-410a": "r410a", "r-32": "r32",
      "outdoor-coil": "condenser-coil",
    }[slug] ?? slug)),
    relatedBrands: relatedBrands[seed.slug],
    keywords: seed.keywords,
  });
}

